-- V160 -- M10.PackUnload: Container Unloading workflow, consolidated.
--
-- This single migration replaces V128/V129/V130/V133 (deleted -- all were
-- still uncommitted, so consolidating is safe). Those four were built
-- incrementally while working through several corrections against actual
-- precedent in this codebase (comparing directly against
-- M10.TankerOutbound's and M10.TankerInbound's real workflow_definitions):
--   - removed a digital PO-exception approval gate that didn't match
--     existing precedent (TankerOutbound captures po_verified/
--     po_override_reason as plain manual fields, no approval workflow)
--   - switched the QC step to aria:qc-preload-approval (used by
--     TankerOutbound/PackLoading/FGLoading) instead of aria:qc-approval
--     (TankerInbound-only), matching the original QC spec more closely
--   - simplified GRN status from a dedicated page/state/approval-table into
--     plain manual fields on aria:reconciliation (visible only for
--     M10.PackUnload), same "manual entry" pattern as PO verification
--   - collapsed the split "Start Unloading" page back into the single
--     shared aria:supervisor-unloading step (Start + Finish captured
--     together), matching M10.TankerInbound's own pattern
--
-- What this migration builds, final state only:
--   - 0 new tables: GRN status/reference capture (not a GRN module --
--     records/verifies a GRN produced by the applicable receiving process,
--     never creates one) lives on unload_reconciliation_detail, the SAME
--     satellite table aria:reconciliation already writes to -- not a
--     separate table
--   - 0 new pages (aria:qc-preload-approval, aria:loading-allocation,
--     aria:weighment-capture, aria:supervisor-unloading, aria:reconciliation,
--     aria:manager-qty-approval, aria:manager-weight-approval,
--     aria:gate-pass-closure, aria:gate-pass-closure-form,
--     aria:dispatch-vehicle-details, aria:front-gate-create are ALL reused
--     as-is, with small gated field additions on 3 of them)
--   - M10.PackUnload's workflow_definition: 16 states, 18 transitions, ZERO
--     Parking Bay states/transitions, ZERO Planning/order-sheet step
--
-- M10.PackLoading is untouched by this file (every gated addition below is
-- additive/inert for it).

-- ============================================================ 1. GRN columns on unload_reconciliation_detail
-- GRN status is manual entry on aria:reconciliation (visible only for
-- M10.PackUnload) -- it belongs on that page's OWN satellite table
-- (unload_reconciliation_detail, already exists, shared with
-- M10.TankerInbound for variance_reason/within_tolerance), not a separate
-- new table. grn_status/grn_number/grn_date/grn_not_required_reason/
-- grn_exception_reason/grn_updated_by are unique field names within this
-- workflow, so they're safe to map generically via m0_workflow_projection --
-- unlike variance_reason/within_tolerance, which stay on
-- ReconciliationDecisionListener (those names ARE reused elsewhere, so they
-- need precise per-page routing).
ALTER TABLE unload_reconciliation_detail
  ADD COLUMN IF NOT EXISTS grn_status VARCHAR(24) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS grn_number VARCHAR(64) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS grn_date DATE DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS grn_not_required_reason VARCHAR(512) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS grn_exception_reason VARCHAR(512) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS grn_updated_by VARCHAR(128) DEFAULT NULL;

INSERT INTO entity_field_registry (id, tenant_id, entity_code, field_code, display_label, data_type, filterable, sortable, searchable, required, widget_kind)
SELECT (SELECT COALESCE(MAX(id),0) FROM entity_field_registry x)+ROW_NUMBER() OVER (ORDER BY c.fc),
       -1,'UnloadReconciliationDetail',c.fc,c.lbl,c.dt,c.filt,c.sort,c.srch,0,c.wk
FROM (SELECT 'grn_status' fc,'GRN Status' lbl,'STRING' dt,1 filt,1 sort,1 srch,'select' wk
      UNION ALL SELECT 'grn_number','GRN Number','STRING',1,1,1,'text'
      UNION ALL SELECT 'grn_date','GRN Date','DATE',1,1,0,'date'
      UNION ALL SELECT 'grn_not_required_reason','GRN Not-Required Reason','STRING',0,0,1,'textarea'
      UNION ALL SELECT 'grn_exception_reason','GRN Exception Reason','STRING',0,0,1,'textarea'
      UNION ALL SELECT 'grn_updated_by','GRN Updated By','STRING',1,1,1,'text') c
WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code='UnloadReconciliationDetail' AND field_code=c.fc);

-- ============================================================ 2. Gated extension: aria:dispatch-vehicle-details
-- Broker/invoice/vendor/PO-verification/dispatch-officer/packing-material
-- fields extended to also show for M10.PackUnload (manual entry, no
-- workflow gate -- po_verified/po_override_reason are captured exactly like
-- M10.TankerOutbound already does). oilRmItem/tankerNo/transportName
-- deliberately left untouched (oil/tanker-specific, not applicable here).
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind": "layout", "schemaVersion": 2, "dataSources": [{"id": "dispatchQueue", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Section", "title": "Dispatch Queue (Open)", "fields": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "dispatchQueue", "pageSize": 25, "cardFields": ["vehicleNo", "gpNumber", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Vehicle & Dispatch Details", "fields": [{"kind": "FormField", "type": "select", "name": "vehicleNo", "label": "Vehicle Number", "required": true, "placeholder": "Select vehicle awaiting dispatch entry", "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "GatePass", "joins": [{"entity": "WorkflowInstance", "as": "wi", "on": "gate_pass.workflow_instance_id = wi.id"}], "filter": {"and": [{"field": "wi.assigned_role", "op": "eq", "value": "Dispatch"}, {"field": "wi.status", "op": "eq", "value": "OPEN"}]}, "select": ["id", "vehicle_no"], "sort": [{"field": "vehicle_no", "dir": "asc"}]}, "valueField": "vehicle_no", "labelField": "vehicle_no"}, "onChangeFill": {"flowVariantCode": "flow_variant_code", "loadingType": "loading_type", "instanceId": "workflow_instance_id"}}, {"kind": "FormField", "type": "text", "name": "flowVariantCode", "label": "Flow Variant", "disabled": true}, {"kind": "FormField", "type": "text", "name": "loadingType", "label": "Loading Type", "disabled": true}, {"kind": "FormField", "type": "text", "name": "instanceId", "label": "Workflow Instance", "disabled": true}, {"kind": "FormField", "type": "select", "name": "ownershipType", "label": "Ownership", "options": ["OWN VEHICLE", "HIRED VEHICLE"]}, {"kind": "FormField", "type": "text", "name": "driverName", "label": "Driver Name"}, {"kind": "FormField", "type": "text", "name": "driverPhone", "label": "Driver Contact"}, {"kind": "FormField", "type": "text", "name": "brokerName", "label": "Broker Details", "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"}, {"kind": "FormField", "type": "text", "name": "invoiceNo", "label": "Invoice No", "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"}, {"kind": "FormField", "type": "number", "name": "invoiceQty", "label": "Invoice Qty", "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"}, {"kind": "FormField", "type": "text", "name": "vendorName", "label": "Vendor Details", "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"}, {"kind": "FormField", "type": "text", "name": "oilRmItem", "label": "Oil RM Details", "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound''"}, {"kind": "FormField", "type": "text", "name": "tankerNo", "label": "Tanker Number", "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound''"}, {"kind": "FormField", "type": "select", "name": "poVerified", "label": "PO Verified", "options": ["YES", "NO - MANAGER APPROVAL"], "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"}, {"kind": "FormField", "type": "text", "name": "poOverrideReason", "label": "Reason (if PO not verified)", "visibleWhen": "(#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES''", "requiredWhen": "(#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES''"}, {"kind": "FormField", "type": "text", "name": "dispatchOfficerName", "label": "Dispatch Front Officer Name", "visibleWhen": "#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"}, {"kind": "FormField", "type": "text", "name": "transportName", "label": "Transport Name", "visibleWhen": "#form.flowVariantCode == ''M10.PackLoading'' || #form.flowVariantCode == ''M10.FGLoading'' || #form.flowVariantCode == ''M10.TankerOutbound''"}, {"kind": "FormField", "type": "textarea", "name": "packingFgStockDetails", "label": "Packing / FG Stock Details", "visibleWhen": "#form.flowVariantCode == ''M10.PackLoading'' || #form.flowVariantCode == ''M10.FGLoading'' || #form.flowVariantCode == ''M10.PackUnload''"}, {"kind": "WorkflowActionButton", "label": "Save Vehicle Details", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "variant": "primary"}]}], "entity": "DispatchVehicleDetail"}'
WHERE pd.code = 'aria:dispatch-vehicle-details' AND pv.body_json NOT LIKE '%M10.PackUnload%';

-- ============================================================ 3. Gated extension: aria:loading-allocation
-- Excludes PackUnload from the OrderApp/M5 dispatch-order fields (same
-- reasoning already applied to M10.TankerInbound -- no OrderApp pipeline
-- for unloading either).
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Loading Supervisor Assign — Queue", "span": 12, "subtitle": "Vehicles approved by QC, awaiting a loading supervisor.", "children": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id"}, "scannable": true, "freeSolo": true}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "loadingBay", "label": "Loading Bay / Point", "type": "select", "visibleWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''", "requiredWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''", "placeholder": "Which bay is this vehicle loading at?", "optionsSource": {"type": "entity", "entity": "LoadingPoint", "valueField": "code", "labelField": "display_name"}}, {"name": "orderRef", "label": "OrderApp Order #", "type": "select", "visibleWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''", "requiredWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''", "placeholder": "Pick the dispatch order this vehicle is loading", "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "OrderAppOrder", "filter": {"field": "vehicle_no", "op": "eq", "value": "pageData:vehicle_no"}, "select": ["order_ref"], "sort": [{"field": "order_ref", "dir": "asc"}]}, "valueField": "order_ref", "labelField": "order_ref"}, "onChangeFill": {"customerName": "customer_name", "orderRoute": "customer_route", "orderedQty": "ordered_weight_kg", "orderedCases": "ordered_cases"}, "scannable": false, "freeSolo": false}, {"name": "customerName", "label": "Customer", "type": "text", "disabled": true, "visibleWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''"}, {"name": "orderRoute", "label": "Route", "type": "text", "disabled": true, "visibleWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''"}, {"name": "orderedCases", "label": "Ordered Cases", "type": "text", "disabled": true, "visibleWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''"}, {"name": "orderedQty", "label": "Ordered Wt (kg)", "type": "text", "disabled": true, "visibleWhen": "#form.flow_variant_code != ''M10.TankerInbound'' && #form.flow_variant_code != ''M10.PackUnload''"}, {"name": "supervisor_name", "label": "Supervisor Name", "type": "select", "required": true, "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "Employee", "select": ["id", "employeename"], "filter": {"and": [{"field": "employeetype", "op": "eq", "value": "Supervisor"}, {"field": "status", "op": "eq", "value": "A"}]}, "sort": [{"field": "employeename", "dir": "asc"}]}, "valueField": "id", "labelField": "employeename"}}]}, "children": [{"kind": "WorkflowActionButton", "label": "Assign Supervisor", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "LOADING_ALLOCATED", "color": "primary"}]}]}]}]}'
