-- ============================================================ 4. Gated extension: aria:front-gate-create
-- Adds Security Officer Name (manual capture) for M10.PackUnload. Built on
-- top of the cascading Loading-Type-to-Flow-Variant structure (a separate,
-- already-applied migration) -- if that structure isn't present yet in some
-- environment, this guard simply no-ops until it is.
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"slug":"aria:front-gate-create","title":"Front Gate — Vehicle Intake","status":"published","version":1,"roles":["FrontGate","TenantAdmin"],"dataSources":[],"streams":[],"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"New Vehicle Intake","span":12,"subtitle":"Capture the vehicle at the gate, then Create Gate Pass to start the selected flow.","children":[{"kind":"Form","submitLabel":"","bindings":{"fields":[{"name":"loadingType","label":"Loading Type","required":true,"type":"select","optionsSource":{"type":"entity","entity":"LoadingType","valueField":"code","labelField":"display_name"}},{"name":"flowVariant","label":"Flow Variant","type":"select","required":true,"placeholder":"Select Loading Type first","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"FlowVariant","filter":{"field":"loading_type_code","op":"eq","value":"pageData:loadingType"},"select":["code","display_name"],"sort":[{"field":"display_name","dir":"asc"}]},"valueField":"code","labelField":"display_name"}},{"name":"vehicleNo","label":"Vehicle No","type":"text","required":true,"placeholder":"TN-46-CJ-0001"},{"name":"vehicleCategory","label":"Vehicle Category","required":true,"type":"select","optionsSource":{"type":"entity","entity":"VehicleCategory","valueField":"code","labelField":"display_name"}},{"name":"securityOfficerName","label":"Security Officer Name","type":"text","visibleWhen":"#form.flowVariant == ''M10.PackUnload''","requiredWhen":"#form.flowVariant == ''M10.PackUnload''"}]},"children":[{"kind":"WorkflowActionButton","label":"Create Gate Pass","action":"workflow.transition","workflowCode":"{{form.flowVariant}}","targetState":"GATE_PASS_CREATED","trigger":"page.submitted","color":"primary","onSuccessOpen":{"page":"aria:gate-pass-slip","lookupEntity":"GatePass","lookupField":"workflow_instance_id","param":"id"}}]}]},{"kind":"Section","title":"Gate Passes In Progress","span":12,"subtitle":"Vehicles you have logged that are moving through parking, weighment and QC.","children":[{"kind":"WorkflowQueueList","persona":"frontgate","pageSize":25,"cardFields":["vehicleNo","gpNumber","currentState"]}]}]}]}'
WHERE pd.code = 'aria:front-gate-create' AND pv.body_json NOT LIKE '%securityOfficerName%';

-- ============================================================ 5. Gated extension: aria:reconciliation
-- Adds GRN Status (+ number/date/reasons/updated-by depending on status) as
-- plain manual-entry fields, visible only for M10.PackUnload -- same manual-
-- entry pattern as po_verified, no separate approval page/state.
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Unload Reconciliation", "span": 12, "subtitle": "Reconcile the unloaded quantity against the order. Within tolerance proceeds; a difference goes to the manager.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "GatePass", "joins": [{"entity": "WorkflowInstance", "as": "wi", "on": "gate_pass.workflow_instance_id = wi.id"}, {"entity": "WeighmentCaptureDetail", "as": "wcd", "on": "wcd.workflow_instance_id = gate_pass.workflow_instance_id", "fields": ["wcd.w1_weight_kg as w1WeightKg", "wcd.w2_weight_kg as w2WeightKg"]}], "filter": {"and": [{"field": "wi.assigned_role", "op": "eq", "value": "Dispatch"}, {"field": "wi.status", "op": "eq", "value": "OPEN"}]}, "select": ["id", "gp_number"], "sort": [{"field": "gp_number", "dir": "desc"}]}, "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "flow_variant_code": "flow_variant_code", "first_weight_kg": "w1WeightKg", "second_weight_kg": "w2WeightKg"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "first_weight_kg", "label": "First Weight (kg)", "type": "number", "readOnly": true}, {"name": "second_weight_kg", "label": "Second Weight (kg)", "type": "number", "readOnly": true}, {"name": "variance_display_kg", "label": "Variance (kg) — auto", "type": "number", "readOnly": true, "computedFrom": "#form.first_weight_kg - #form.second_weight_kg"}, {"name": "variance_reason", "label": "Variance reason (if any)", "type": "textarea"}, {"name": "grn_status", "label": "GRN Status", "type": "select", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload''", "options": [{"label": "Pending", "value": "GRN_PENDING"}, {"label": "Completed", "value": "GRN_COMPLETED"}, {"label": "Not Required", "value": "GRN_NOT_REQUIRED"}, {"label": "Exception", "value": "GRN_EXCEPTION"}]}, {"name": "grn_number", "label": "GRN Number", "type": "text", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''"}, {"name": "grn_date", "label": "GRN Date", "type": "date", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''"}, {"name": "grn_not_required_reason", "label": "Reason GRN Not Required", "type": "textarea", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_NOT_REQUIRED''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_NOT_REQUIRED''"}, {"name": "grn_exception_reason", "label": "GRN Exception Reason", "type": "textarea", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_EXCEPTION''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_EXCEPTION''"}, {"name": "grn_updated_by", "label": "GRN Updated By", "type": "text", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload''"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Reconciled — Within Tolerance", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "primary", "submitValues": {"withinTolerance": "YES"}}, {"kind": "WorkflowActionButton", "label": "⚠ Difference → Manager", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "error", "submitValues": {"withinTolerance": "NO"}}]}]}]}]}'
WHERE pd.code = 'aria:reconciliation' AND pv.body_json NOT LIKE '%grn_status%';

-- ============================================================ 6. Workflow definition
