SET body_json = '{"code":"M10.PackUnload","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"Dispatch"},{"code":"DISPATCH_VEHICLE_ENTRY","assignedRole":"QC"},{"code":"QC_APPROVED","assignedRole":"Dispatch"},{"code":"QC_REJECTED","terminal":true},{"code":"UNLOADING_ALLOCATED","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_1","assignedRole":"UnloadingSupervisor"},{"code":"UNLOADING_COMPLETED","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_2","assignedRole":"Dispatch"},{"code":"QUANTITY_RECONCILIATION","assignedRole":"Dispatch"},{"code":"QUANTITY_APPROVAL_PENDING","assignedRole":"Manager"},{"code":"WEIGHMENT_3","assignedRole":"FrontGate"},{"code":"WEIGHT_APPROVAL_PENDING","assignedRole":"Manager"},{"code":"READY_FOR_EXIT","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true},{"code":"REJECTED_BY_MANAGER","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"aria:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"DISPATCH_VEHICLE_ENTRY","trigger":"page.submitted","pageCode":"aria:dispatch-vehicle-details"},{"from":"DISPATCH_VEHICLE_ENTRY","to":"QC_APPROVED","trigger":"page.submitted","pageCode":"aria:qc-preload-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"DISPATCH_VEHICLE_ENTRY","to":"QC_REJECTED","trigger":"page.submitted","pageCode":"aria:qc-preload-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_APPROVED","to":"UNLOADING_ALLOCATED","trigger":"page.submitted","pageCode":"aria:loading-allocation"},{"from":"UNLOADING_ALLOCATED","to":"WEIGHMENT_1","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_1","to":"UNLOADING_COMPLETED","trigger":"page.submitted","pageCode":"aria:supervisor-unloading"},{"from":"UNLOADING_COMPLETED","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_2","to":"QUANTITY_RE